export type ParsedOpenJointPaymentInstruction<
  TProgram extends string = typeof CLEARING_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    payer: TAccountMetas[0];
    payment: TAccountMetas[1];
    prepared: TAccountMetas[2];
    resolution: TAccountMetas[3];
    rates: TAccountMetas[4];
    btcPairs: TAccountMetas[5];
    ethPairs: TAccountMetas[6];
    btcAllocation: TAccountMetas[7];
    ethAllocation: TAccountMetas[8];
    systemProgram: TAccountMetas[9];
  };
  data: OpenJointPaymentInstructionData;
};

export function parseOpenJointPaymentInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedOpenJointPaymentInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 10) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 10,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      payer: getNextAccount(),
      payment: getNextAccount(),
      prepared: getNextAccount(),
      resolution: getNextAccount(),
      rates: getNextAccount(),
      btcPairs: getNextAccount(),
      ethPairs: getNextAccount(),
      btcAllocation: getNextAccount(),
      ethAllocation: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getOpenJointPaymentInstructionDataDecoder().decode(instruction.data),
  };
}
